9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner == null ? null : owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(owner == null ? null : "
25	            + "Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
26	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
27	    @Mapping(target = "locality", expression = "java(deriveLocality(owner))")
28	    @Mapping(target = "contactPreference",
29	        expression = "java(owner == null ? null : "
30	            + "(owner.getEmail() != null && !owner.getEmail().isEmpty() ? \"EMAIL\" : \"PHONE\"))")
31	    @Mapping(target = "identityKey",
32	        expression = "java(owner == null ? null : owner.getTelephone() + \"|\" "
33	            + "+ (owner.getEmail() == null ? \"\" : owner.getEmail()) + \"|\" "
34	            + "+ (owner.getHouseholdId() == null ? \"\" : owner.getHouseholdId()))")
35	    @Mapping(target = "checkDigit", expression = "java(deriveCheckDigit(owner))")
36	    @Mapping(target = "ageBand", expression = "java(deriveAgeBand(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    Owner toOwner(OwnerDto ownerDto);
40	
41	    @Mapping(target = "id", ignore = true)
42	    @Mapping(target = "pets", ignore = true)
43	    Owner toOwner(OwnerFieldsDto ownerDto);
44	
45	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
46	
47	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
48	
49	    /**
50	     * Derive the owner's locality (region) from its region-and-hash {@code customerCode}: the
51	     * {@code REGION} portion is the segment before the first {@code '-'} (e.g. {@code "NSW-1A2B3C4D"}
52	     * yields {@code "NSW"}). This shares the identity's region derivation, where the postcode range
53	     * takes precedence (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and the city-to-region table is
54	     * the fallback. For an owner without a {@code customerCode} the same region is recomputed directly
55	     * from the postcode then city, otherwise "UNKNOWN".
56	     */
57	    default String deriveLocality(Owner owner) {
58	        if (owner == null) {
59	            return null;
60	        }
61	        String customerCode = owner.getCustomerCode();
62	        if (customerCode != null) {
63	            int dash = customerCode.indexOf('-');
64	            if (dash > 0) {
65	                return customerCode.substring(0, dash);
66	            }
67	        }
68	        String postcode = owner.getPostcode();
69	        if (postcode != null) {
70	            try {
71	                int pc = Integer.parseInt(postcode.trim());
72	                if (pc >= 2000 && pc <= 2099) {
73	                    return "NSW";
74	                }
75	                if (pc >= 3000 && pc <= 3099) {
76	                    return "VIC";
77	                }
78	                if (pc >= 4000 && pc <= 4099) {
79	                    return "QLD";
80	                }
81	            }
82	            catch (NumberFormatException ignored) {
83	                // not a numeric postcode; fall back to the city-to-region table
84	            }
85	        }
86	        String city = owner.getCity();
87	        if ("Sydney".equals(city)) {
88	            return "NSW";
89	        }
90	        if ("Melbourne".equals(city)) {
91	            return "VIC";
92	        }
93	        if ("Brisbane".equals(city)) {
94	            return "QLD";
95	        }
96	        return "UNKNOWN";
97	    }
98	
99	    /**
100	     * Derive the owner's check digit: a single Luhn check digit (0-9) computed over the
101	     * digits contained in the owner's customerCode. Non-digit characters are ignored.
102	     * Returns null when the owner or its customerCode is absent.
103	     */
104	    default Integer deriveCheckDigit(Owner owner) {
105	        if (owner == null || owner.getCustomerCode() == null) {
106	            return null;
107	        }
108	        String code = owner.getCustomerCode();
109	        int sum = 0;
110	        boolean dbl = true;
111	        for (int i = code.length() - 1; i >= 0; i--) {
112	            char c = code.charAt(i);
113	            if (c < '0' || c > '9') {
114	                continue;
115	            }
116	            int d = c - '0';
117	            if (dbl) {
118	                d *= 2;
119	                if (d > 9) {
120	                    d -= 9;
121	                }
122	            }
123	            sum += d;
124	            dbl = !dbl;
125	        }
126	        return (10 - (sum % 10)) % 10;
127	    }
128	
129	    /**
130	     * Derive the owner's age band from its birthDate against the registrationDate: 'MINOR' when
131	     * under 18, 'ADULT' from 18 to 64, and 'SENIOR' at 65 or older. The age is the number of whole
132	     * years between birthDate and registrationDate (falling back to the current date when the owner
133	     * has no registrationDate). Returns null when the owner or its birthDate is absent, so no
134	     * ageBand is reported.
135	     */
136	    default String deriveAgeBand(Owner owner) {
137	        if (owner == null || owner.getBirthDate() == null) {
138	            return null;
139	        }
140	        java.time.LocalDate reference = owner.getRegistrationDate() != null
141	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
142	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
143	        if (age < 18) {
144	            return "MINOR";
145	        }
146	        if (age < 65) {
