        expression = "java(owner == null ? null : owner.getTelephone() + \"|\" "
            + "+ (owner.getEmail() == null ? \"\" : owner.getEmail()) + \"|\" "
            + "+ (owner.getHouseholdId() == null ? \"\" : owner.getHouseholdId()))")
    @Mapping(target = "checkDigit", expression = "java(deriveCheckDigit(owner))")
